Status Clock::dispatch(uint8_t cmd_id, std::span<const uint8_t> args, Reply &reply)
{
    switch (cmd_id) {
    case kCmdRead: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        const auto r = read();
        if (!r) {
            return std::unexpected(r.error());
        }
        encode(*r, reply.fields());
        // Fields beyond the caller's buffer (realtime or bulk): FAILED with no fields, never truncated ones.
        if (reply.fields().overflow()) {
            reply.clear();
            return std::unexpected(Err::failed);
        }
        return {};
    }
    case kCmdSet: {
        const auto a = decode_clock_set_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return set(*a);
    }
    case kCmdSetAging: {
        const auto a = decode_clock_set_aging_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return set_aging(*a);
    }
#if FR_TEST_HOOKS
    case kCmdInject: {
        const auto a = decode_clock_inject_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return inject(*a);
    }
#endif
    default:
        return std::unexpected(Err::unsupported);
    }
}

