void Clock::emit_set(const ClockSet &e, TimeUs at)
{
    if (sink_ == nullptr) {
        return;
    }
    uint8_t buf[ClockSet::kMaxSize];
    fr::wire::Writer w(buf, sizeof(buf));
    encode(e, w);
    sink_->event(port_, kEventSet, Priority::normal, w.bytes(), at, kOrdered);
}

